/* =====================================================================
   FLOCK WEIGHT MANAGEMENT & ANALYSIS SYSTEM
   Script 07 : Seed data for Phases 2-5  (generated by tools/gen_seed_phase2.py)
     - permissions + menus for every Phase 2-5 screen and their role mapping
     - SAMPLE age/week standards for Female Breeder, Male Breeder, Parent Stock
       (illustrative curves: REPLACE WITH YOUR BREED MANAGEMENT GUIDE before go-live)
     - one feed formula per feed type
     - weekly sample data for flocks F001, F002, F003 (includes deliberate problems
       so the dashboard, alerts and exception report have something to show)
   Run once after 03-06 on the same day as 03 (sample hatch dates are relative to today).
   ===================================================================== */
USE FlockManagementDB;
GO
SET NOCOUNT ON;
SET XACT_ABORT ON;
GO
IF EXISTS (SELECT 1 FROM dbo.tblPermissions WHERE PermissionCode = N'TXN_WEEKLY')
BEGIN
    RAISERROR(N'Phase 2-5 seed data already present. Script stopped.', 16, 1);
    SET NOEXEC ON;
END
GO
BEGIN TRANSACTION;

