DECLARE @rAdmin INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Administrator');
DECLARE @rMgr   INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Farm Manager');
DECLARE @rSup   INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Farm Supervisor');
DECLARE @rNut   INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Nutritionist');
DECLARE @rVet   INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Veterinarian');
DECLARE @rDEO   INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Data Entry Operator');
DECLARE @rView  INT = (SELECT RoleID FROM dbo.tblRoles WHERE RoleName = N'Management / Viewer');

DECLARE @new TABLE (PermissionID INT, Code NVARCHAR(60));
INSERT INTO @new SELECT PermissionID, PermissionCode FROM dbo.tblPermissions p
WHERE NOT EXISTS (SELECT 1 FROM dbo.tblRolePermissions rp WHERE rp.PermissionID = p.PermissionID);

DECLARE @views TABLE (Code NVARCHAR(60));
INSERT INTO @views VALUES (N'FEEDFORMULA_VIEW'), (N'MORTREASON_VIEW'), (N'STANDARD_VIEW'), (N'PLACEMENT_VIEW'), (N'WEEKLY_VIEW'),
 (N'TRANSFER_VIEW'), (N'ADJUST_VIEW'), (N'ANALYSIS_WEEKLY'), (N'ANALYSIS_SVA'), (N'ANALYSIS_WEIGHT'), (N'ANALYSIS_FEED'),
 (N'ANALYSIS_NUTRITION'), (N'ANALYSIS_UNIFORMITY'), (N'ANALYSIS_MORTALITY'), (N'ANALYSIS_TREND'), (N'ANALYSIS_COMPARE'),
 (N'EXCEPTION_VIEW'), (N'ALERT_VIEW'), (N'REPORT_VIEW'), (N'REPORT_EXPORT');
DECLARE @entry TABLE (Code NVARCHAR(60));
INSERT INTO @entry VALUES (N'TXN_WEEKLY'), (N'TXN_BODYWEIGHT'), (N'TXN_FEED'), (N'TXN_NUTRITION'), (N'TXN_MORTALITY');

INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rAdmin, PermissionID FROM @new;
INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rMgr, PermissionID FROM @new;  -- managers: everything incl. adjustments and configuration
INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rSup, PermissionID FROM @new
 WHERE Code IN (SELECT Code FROM @views) OR Code IN (SELECT Code FROM @entry) OR Code IN (N'PLACEMENT_EDIT', N'TRANSFER_EDIT', N'ALERT_ACK');
INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rNut, PermissionID FROM @new
 WHERE Code IN (SELECT Code FROM @views) OR Code IN (N'TXN_NUTRITION', N'FEEDFORMULA_EDIT', N'STANDARD_EDIT', N'ALERT_ACK');
INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rVet, PermissionID FROM @new
 WHERE Code IN (SELECT Code FROM @views) OR Code IN (N'TXN_MORTALITY', N'MORTREASON_EDIT', N'ALERT_ACK');
INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rDEO, PermissionID FROM @new
 WHERE Code IN (SELECT Code FROM @entry) OR Code IN (N'WEEKLY_VIEW', N'PLACEMENT_VIEW', N'ANALYSIS_WEEKLY', N'ALERT_VIEW');
INSERT INTO dbo.tblRolePermissions (RoleID, PermissionID) SELECT @rView, PermissionID FROM @new
 WHERE Code IN (SELECT Code FROM @views);

/* the dashboard now shows analysis KPIs: give it to every role that can analyse */

