INSERT INTO dbo.tblStandard (BirdTypeID, BreedID, FeedTypeID, AgeWeek, ParameterID, StandardValue, MinValue, MaxValue,
                             CriticalMinValue, CriticalMaxValue, UnitID, EffectiveFrom, IsActive, CreatedBy)
SELECT CASE s.BirdType WHEN 'FB' THEN @btF WHEN 'MB' THEN @btM ELSE @btP END, NULL, NULL, s.AgeWeek, p.ParameterID,
       s.StdV, s.MinV, s.MaxV, s.CMinV, s.CMaxV, p.UnitID, '2020-01-01', 1, @admin
FROM @std s INNER JOIN dbo.tblParameter p ON p.ParameterCode = s.Code;

