/* ---------- sample weekly data (each week saved through sp_FlockWeekly_Save, like the screen does) ---------- */
BEGIN TRANSACTION;
DECLARE @admin INT = (SELECT UserID FROM dbo.tblUsers WHERE UserName = N'admin');
DECLARE @id INT, @d DATE, @h DATE, @flock INT, @fj NVARCHAR(MAX), @mj NVARCHAR(MAX), @nj NVARCHAR(MAX);
DECLARE @ftBST INT = (SELECT FeedTypeID FROM dbo.tblFeedType WHERE FeedTypeCode = N'BST');
DECLARE @ftDEV INT = (SELECT FeedTypeID FROM dbo.tblFeedType WHERE FeedTypeCode = N'DEV');
DECLARE @ftBPL INT = (SELECT FeedTypeID FROM dbo.tblFeedType WHERE FeedTypeCode = N'BPL');
DECLARE @ftBL1 INT = (SELECT FeedTypeID FROM dbo.tblFeedType WHERE FeedTypeCode = N'BL1');
DECLARE @ftMALE INT = (SELECT FeedTypeID FROM dbo.tblFeedType WHERE FeedTypeCode = N'MALE');
DECLARE @ffBST INT = (SELECT FeedFormulaID FROM dbo.tblFeedFormula WHERE FormulaCode = N'BST-2026-01');
DECLARE @ffDEV INT = (SELECT FeedFormulaID FROM dbo.tblFeedFormula WHERE FormulaCode = N'DEV-2026-01');
DECLARE @ffBPL INT = (SELECT FeedFormulaID FROM dbo.tblFeedFormula WHERE FormulaCode = N'BPL-2026-01');
DECLARE @ffBL1 INT = (SELECT FeedFormulaID FROM dbo.tblFeedFormula WHERE FormulaCode = N'BL1-2026-01');
DECLARE @ffMALE INT = (SELECT FeedFormulaID FROM dbo.tblFeedFormula WHERE FormulaCode = N'MALE-2026-01');
DECLARE @rNAT INT = (SELECT MortalityReasonID FROM dbo.tblMortalityReason WHERE ReasonCode = N'NAT');
DECLARE @rRESP INT = (SELECT MortalityReasonID FROM dbo.tblMortalityReason WHERE ReasonCode = N'RESP');
DECLARE @rLEG INT = (SELECT MortalityReasonID FROM dbo.tblMortalityReason WHERE ReasonCode = N'LEG');
DECLARE @rCULL INT = (SELECT MortalityReasonID FROM dbo.tblMortalityReason WHERE ReasonCode = N'CULL');

SELECT @flock = FlockID, @h = HatchDate FROM dbo.tblFlock WHERE FlockNumber = N'F001';
SET @d = DATEADD(DAY, 7, @h);
SET @fj = CONCAT(N'[{"feedTypeId":', @ftBST, N',"formulaId":', @ffBST, N',"sex":"F","qty":1742.1,"waste":10.2}]');
SET @mj = CONCAT(N'[{"reasonId":', @rNAT, N',"sex":"F","count":41}', N',{"reasonId":', @rRESP, N',"sex":"F","count":18}', N']');
EXEC dbo.sp_FlockWeekly_Save @FlockWeeklyID = 0, @FlockID = @flock, @WeekNo = 1, @EntryDate = @d, @FeedTypeID = @ftBST, @FeedFormulaID = @ffBST, @MaleMortality = 0, @FemaleMortality = 59, @MaleCulling = 0, @FemaleCulling = 0, @NutritionSource = 'F', @LabSampleRef = NULL, @AnalysisDate = NULL, @SamplesJson = N'[{"sex":"F","w":120.0},{"sex":"F","w":135.0},{"sex":"F","w":107.0},{"sex":"F","w":115.0},{"sex":"F","w":107.0},{"sex":"F","w":120.0},{"sex":"F","w":125.0},{"sex":"F","w":125.0},{"sex":"F","w":126.0},{"sex":"F","w":117.0},{"sex":"F","w":115.0},{"sex":"F","w":132.0},{"sex":"F","w":128.0},{"sex":"F","w":123.0},{"sex":"F","w":109.0},{"sex":"F","w":136.0},{"sex":"F","w":129.0},{"sex":"F","w":123.0},{"sex":"F","w":135.0},{"sex":"F","w":110.0},{"sex":"F","w":117.0},{"sex":"F","w":117.0},{"sex":"F","w":130.0},{"sex":"F","w":108.0},{"sex":"F","w":130.0},{"sex":"F","w":121.0},{"sex":"F","w":116.0},{"sex":"F","w":122.0},{"sex":"F","w":126.0},{"sex":"F","w":107.0},{"sex":"F","w":116.0},{"sex":"F","w":116.0},{"sex":"F","w":113.0},{"sex":"F","w":124.0},{"sex":"F","w":119.0},{"sex":"F","w":134.0},{"sex":"F","w":122.0},{"sex":"F","w":136.0},{"sex":"F","w":114.0},{"sex":"F","w":101.0}]', @FeedJson = @fj, @NutrientsJson = NULL, @MortalityJson = @mj, @UserID = @admin, @UserName = N'admin', @IPAddress = N'seed', @NewFlockWeeklyID = @id OUTPUT;
SET @d = DATEADD(DAY, 14, @h);
SET @fj = CONCAT(N'[{"feedTypeId":', @ftBST, N',"formulaId":', @ffBST, N',"sex":"F","qty":2177.6,"waste":5.4}]');
SET @mj = CONCAT(N'[{"reasonId":', @rNAT, N',"sex":"F","count":15}', N',{"reasonId":', @rRESP, N',"sex":"F","count":6}', N']');
EXEC dbo.sp_FlockWeekly_Save @FlockWeeklyID = 0, @FlockID = @flock, @WeekNo = 2, @EntryDate = @d, @FeedTypeID = @ftBST, @FeedFormulaID = @ffBST, @MaleMortality = 0, @FemaleMortality = 21, @MaleCulling = 0, @FemaleCulling = 0, @NutritionSource = 'F', @LabSampleRef = NULL, @AnalysisDate = NULL, @SamplesJson = N'[{"sex":"F","w":264.0},{"sex":"F","w":215.0},{"sex":"F","w":229.0},{"sex":"F","w":246.0},{"sex":"F","w":245.0},{"sex":"F","w":240.0},{"sex":"F","w":227.0},{"sex":"F","w":258.0},{"sex":"F","w":217.0},{"sex":"F","w":259.0},{"sex":"F","w":239.0},{"sex":"F","w":228.0},{"sex":"F","w":238.0},{"sex":"F","w":243.0},{"sex":"F","w":238.0},{"sex":"F","w":233.0},{"sex":"F","w":236.0},{"sex":"F","w":240.0},{"sex":"F","w":266.0},{"sex":"F","w":249.0},{"sex":"F","w":247.0},{"sex":"F","w":252.0},{"sex":"F","w":241.0},{"sex":"F","w":261.0},{"sex":"F","w":241.0},{"sex":"F","w":246.0},{"sex":"F","w":242.0},{"sex":"F","w":267.0},{"sex":"F","w":226.0},{"sex":"F","w":252.0},{"sex":"F","w":236.0},{"sex":"F","w":243.0},{"sex":"F","w":252.0},{"sex":"F","w":259.0},{"sex":"F","w":259.0},{"sex":"F","w":200.0},{"sex":"F","w":247.0},{"sex":"F","w":254.0},{"sex":"F","w":276.0},{"sex":"F","w":254.0}]', @FeedJson = @fj, @NutrientsJson = NULL, @MortalityJson = @mj, @UserID = @admin, @UserName = N'admin', @IPAddress = N'seed', @NewFlockWeeklyID = @id OUTPUT;
SET @d = DATEADD(DAY, 21, @h);
SET @fj = CONCAT(N'[{"feedTypeId":', @ftBST, N',"formulaId":', @ffBST, N',"sex":"F","qty":2599.1,"waste":15.3}]');
SET @mj = CONCAT(N'[{"reasonId":', @rNAT, N',"sex":"F","count":11}', N',{"reasonId":', @rRESP, N',"sex":"F","count":5}', N',{"reasonId":', @rCULL, N',"sex":"F","count":2}', N']');
EXEC dbo.sp_FlockWeekly_Save @FlockWeeklyID = 0, @FlockID = @flock, @WeekNo = 3, @EntryDate = @d, @FeedTypeID = @ftBST, @FeedFormulaID = @ffBST, @MaleMortality = 0, @FemaleMortality = 16, @MaleCulling = 0, @FemaleCulling = 2, @NutritionSource = 'F', @LabSampleRef = NULL, @AnalysisDate = NULL, @SamplesJson = N'[{"sex":"F","w":344.0},{"sex":"F","w":403.0},{"sex":"F","w":326.0},{"sex":"F","w":361.0},{"sex":"F","w":374.0},{"sex":"F","w":356.0},{"sex":"F","w":308.0},{"sex":"F","w":358.0},{"sex":"F","w":357.0},{"sex":"F","w":369.0},{"sex":"F","w":405.0},{"sex":"F","w":412.0},{"sex":"F","w":377.0},{"sex":"F","w":360.0},{"sex":"F","w":316.0},{"sex":"F","w":332.0},{"sex":"F","w":348.0},{"sex":"F","w":374.0},{"sex":"F","w":356.0},{"sex":"F","w":437.0},{"sex":"F","w":349.0},{"sex":"F","w":388.0},{"sex":"F","w":363.0},{"sex":"F","w":390.0},{"sex":"F","w":318.0},{"sex":"F","w":377.0},{"sex":"F","w":373.0},{"sex":"F","w":300.0},{"sex":"F","w":338.0},{"sex":"F","w":423.0},{"sex":"F","w":356.0},{"sex":"F","w":395.0},{"sex":"F","w":337.0},{"sex":"F","w":410.0},{"sex":"F","w":328.0},{"sex":"F","w":399.0},{"sex":"F","w":398.0},{"sex":"F","w":369.0},{"sex":"F","w":384.0},{"sex":"F","w":406.0}]', @FeedJson = @fj, @NutrientsJson = NULL, @MortalityJson = @mj, @UserID = @admin, @UserName = N'admin', @IPAddress = N'seed', @NewFlockWeeklyID = @id OUTPUT;
SET @d = DATEADD(DAY, 28, @h);
